import { prisma } from '../db.js';

export interface ResolveTeamHints {
  gender?: string; // 'male' | 'female'
  teamType?: string; // 'international' | 'club'
  country?: string;
  source?: 'cricsheet' | 'cricketdata' | 'manual';
}

export interface ResolveVenueHints {
  city?: string | null;
  country?: string | null;
  source?: 'cricsheet' | 'cricketdata' | 'manual';
}

// Pure Jaro-Winkler similarity implementation
export function jaroWinkler(s1: string, s2: string): number {
  if (s1 === s2) return 1.0;
  if (!s1 || !s2) return 0.0;

  const a = s1.toLowerCase();
  const b = s2.toLowerCase();

  const matchDistance = Math.floor(Math.max(a.length, b.length) / 2) - 1;
  const aMatches = new Array(a.length).fill(false);
  const bMatches = new Array(b.length).fill(false);

  let matches = 0;
  for (let i = 0; i < a.length; i++) {
    const start = Math.max(0, i - matchDistance);
    const end = Math.min(i + matchDistance + 1, b.length);

    for (let j = start; j < end; j++) {
      if (bMatches[j]) continue;
      if (a[i] !== b[j]) continue;
      aMatches[i] = true;
      bMatches[j] = true;
      matches++;
      break;
    }
  }

  if (matches === 0) return 0.0;

  let transpositions = 0;
  let k = 0;
  for (let i = 0; i < a.length; i++) {
    if (!aMatches[i]) continue;
    while (!bMatches[k]) k++;
    if (a[i] !== b[k]) transpositions++;
    k++;
  }

  const jaro =
    (matches / a.length + matches / b.length + (matches - transpositions / 2) / matches) / 3;

  // Winkler prefix scaling (up to 4 chars)
  let prefix = 0;
  for (let i = 0; i < Math.min(4, Math.min(a.length, b.length)); i++) {
    if (a[i] === b[i]) prefix++;
    else break;
  }

  return jaro + prefix * 0.1 * (1 - jaro);
}

// Normalize team name & extract gender hint if present
export function normalizeTeamName(rawName: string, explicitGender?: string): {
  normalized: string;
  gender: string;
  isYouthOrA: boolean;
} {
  let name = rawName.trim();
  let gender = explicitGender || 'male';

  const lower = name.toLowerCase();
  if (lower.endsWith(' women') || lower.endsWith(' w') || lower.endsWith(' female') || lower.includes('women')) {
    gender = 'female';
    name = name.replace(/\b(women|w|female)\b/gi, '').trim();
  }

  // Preserve 'A' team or 'U19'/'Under-19' distinction - NEVER strip
  const isYouthOrA =
    /\b(A team|team A|\bA\b|U19|Under-19|U-19|U23|Academy)\b/i.test(name);

  // Strip punctuation but keep alphanumeric and spaces
  const normalized = name
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return { normalized, gender, isYouthOrA };
}

// Normalize venue name for key comparison
export function normalizeVenueName(rawName: string): string {
  return rawName
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\b(stadium|ground|international|cricket|park|oval|sports|complex|arena)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Resolve Team with strict gender separation and no cross-senior/youth fuzzy matching.
 */
export async function resolveTeam(
  rawName: string,
  hints: ResolveTeamHints = {}
): Promise<{ teamId: string; name: string; isNew: boolean }> {
  const source = hints.source || 'cricsheet';
  const { normalized, gender, isYouthOrA } = normalizeTeamName(rawName, hints.gender);
  const teamType = hints.teamType || 'international';

  // 1. Direct Alias lookup in DB
  const existingAlias = await prisma.teamAlias.findFirst({
    where: {
      alias: rawName.trim(),
    },
    include: { team: true },
  });

  if (existingAlias && existingAlias.team.gender === gender) {
    return { teamId: existingAlias.team.id, name: existingAlias.team.name, isNew: false };
  }

  // 2. Canonical exact name match with same gender
  const exactTeam = await prisma.team.findFirst({
    where: {
      name: { equals: rawName.trim(), mode: 'insensitive' },
      gender,
    },
  });

  if (exactTeam) {
    // Record alias
    await prisma.teamAlias.upsert({
      where: { alias_source: { alias: rawName.trim(), source } },
      create: { alias: rawName.trim(), source, teamId: exactTeam.id },
      update: {},
    });
    return { teamId: exactTeam.id, name: exactTeam.name, isNew: false };
  }

  // 3. For Cricsheet import: Upsert new canonical team
  if (source === 'cricsheet' || source === 'manual') {
    const code = (rawName.replace(/[^A-Za-z]/g, '').slice(0, 3).toUpperCase() + '_' + gender[0].toUpperCase() + '_' + Math.random().toString(36).substring(2, 5)).toUpperCase();
    const newTeam = await prisma.team.create({
      data: {
        name: rawName.trim(),
        shortName: rawName.slice(0, 15).trim(),
        code,
        gender,
        teamType,
        country: hints.country || null,
      },
    });

    await prisma.teamAlias.upsert({
      where: { alias_source: { alias: rawName.trim(), source } },
      create: { alias: rawName.trim(), source, teamId: newTeam.id },
      update: { teamId: newTeam.id },
    });

    return { teamId: newTeam.id, name: newTeam.name, isNew: true };
  }

  // 4. Provider Match: Record unmapped entity if cannot resolve
  await prisma.unmappedEntity.upsert({
    where: {
      kind_rawValue_source: {
        kind: 'team',
        rawValue: rawName.trim(),
        source,
      },
    },
    create: {
      kind: 'team',
      rawValue: rawName.trim(),
      source,
      count: 1,
    },
    update: {
      count: { increment: 1 },
      lastSeen: new Date(),
    },
  });

  throw new Error(`Unmapped team: ${rawName} (${gender}) from ${source}`);
}

/**
 * Resolve Venue using normalized key matching and conservative similarity (> 0.93).
 */
export async function resolveVenue(
  rawName: string,
  hints: ResolveVenueHints = {}
): Promise<{ venueId: string; name: string; isNew: boolean }> {
  const source = hints.source || 'cricsheet';
  const cleanName = rawName.trim();
  const cleanCity = hints.city ? hints.city.trim() : null;
  const normKey = normalizeVenueName(cleanName);

  // 1. Direct Alias Match
  const existingAlias = await prisma.venueAlias.findFirst({
    where: { alias: cleanName },
    include: { venue: true },
  });

  if (existingAlias) {
    return { venueId: existingAlias.venue.id, name: existingAlias.venue.name, isNew: false };
  }

  // 2. Exact or Normalized Match
  const candidates = await prisma.venue.findMany({
    where: cleanCity
      ? {
          OR: [
            { name: { equals: cleanName, mode: 'insensitive' } },
            { city: { equals: cleanCity, mode: 'insensitive' } },
          ],
        }
      : {
          name: { equals: cleanName, mode: 'insensitive' },
        },
  });

  for (const cand of candidates) {
    if (cand.name.toLowerCase() === cleanName.toLowerCase()) {
      await prisma.venueAlias.upsert({
        where: { alias_source: { alias: cleanName, source } },
        create: { alias: cleanName, source, venueId: cand.id },
        update: {},
      });
      return { venueId: cand.id, name: cand.name, isNew: false };
    }

    const candNorm = normalizeVenueName(cand.name);
    if (candNorm && normKey && candNorm === normKey) {
      await prisma.venueAlias.upsert({
        where: { alias_source: { alias: cleanName, source } },
        create: { alias: cleanName, source, venueId: cand.id },
        update: {},
      });
      return { venueId: cand.id, name: cand.name, isNew: false };
    }

    // Conservative fuzzy match > 0.93 only if cities match
    if (cleanCity && cand.city && cleanCity.toLowerCase() === cand.city.toLowerCase()) {
      const sim = jaroWinkler(normKey, candNorm);
      if (sim >= 0.93) {
        await prisma.venueAlias.upsert({
          where: { alias_source: { alias: cleanName, source } },
          create: { alias: cleanName, source, venueId: cand.id },
          update: {},
        });
        return { venueId: cand.id, name: cand.name, isNew: false };
      }
    }
  }

  // 3. For Cricsheet import: Create canonical Venue
  if (source === 'cricsheet' || source === 'manual') {
    const newVenue = await prisma.venue.create({
      data: {
        name: cleanName,
        city: cleanCity,
        country: hints.country || null,
      },
    });

    await prisma.venueAlias.upsert({
      where: { alias_source: { alias: cleanName, source } },
      create: { alias: cleanName, source, venueId: newVenue.id },
      update: { venueId: newVenue.id },
    });

    return { venueId: newVenue.id, name: newVenue.name, isNew: true };
  }

  // 4. Provider Match: Record unmapped entity
  await prisma.unmappedEntity.upsert({
    where: {
      kind_rawValue_source: {
        kind: 'venue',
        rawValue: cleanName,
        source,
      },
    },
    create: {
      kind: 'venue',
      rawValue: cleanName,
      source,
      count: 1,
    },
    update: {
      count: { increment: 1 },
      lastSeen: new Date(),
    },
  });

  throw new Error(`Unmapped venue: ${cleanName} (${cleanCity}) from ${source}`);
}
